  5	const SCHEMA = `
  6	CREATE TABLE IF NOT EXISTS jobs (
  7	  seq INTEGER PRIMARY KEY AUTOINCREMENT,
  8	  id TEXT NOT NULL UNIQUE,
  9	  status TEXT NOT NULL CHECK (status IN ('queued', 'running', 'completed', 'failed')),
 10	  input TEXT NOT NULL,
 11	  steps INTEGER NOT NULL,
 12	  fail_attempts INTEGER NOT NULL,
 13	  attempts INTEGER NOT NULL DEFAULT 0,
 14	  progress_completed INTEGER NOT NULL DEFAULT 0,
 15	  result_output TEXT,
 16	  error TEXT,
 17	  idempotency_key TEXT UNIQUE,
 18	  run_after INTEGER NOT NULL DEFAULT 0,
 19	  created_at TEXT NOT NULL,
 20	  updated_at TEXT NOT NULL
 21	);
 22	CREATE INDEX IF NOT EXISTS jobs_queue ON jobs (status, run_after, seq);
 23	CREATE TABLE IF NOT EXISTS worker_heartbeat (
 24	  id INTEGER PRIMARY KEY CHECK (id = 1),
 25	  beat_at INTEGER NOT NULL
 26	);
 27	`;
