 29	/** Opens the SQLite database shared by the server and worker processes, creating the schema if needed. */
 30	export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
 31	  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
 32	  const db = new DatabaseSync(path);
 33	  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
 34	  // open the same database at once, so the loser must wait rather than fail.
 35	  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;');
 36	  db.exec(SCHEMA);
 37	  return db;
 38	}
 39	
 40	/** Runs `fn` inside a write transaction that takes the write lock up front. */
 41	export function transaction<T>(db: DatabaseSync, fn: () => T): T {
 42	  db.exec('BEGIN IMMEDIATE');
 43	  try {
 44	    const result = fn();
 45	    db.exec('COMMIT');
 46	    return result;
 47	  } catch (e) {
 48	    db.exec('ROLLBACK');
 49	    throw e;
 50	  }
 51	}
