  5	/** Total processing attempts allowed for a job that keeps failing transiently. */
  6	export const MAX_ATTEMPTS = 3;
  7	/** Delay before a failed attempt is retried. Must lie between 250 ms and 2 s. */
  8	export const RETRY_DELAY_MS = 500;
  9	export const TRANSIENT_ERROR = 'transient failure';
 10	/** The worker counts as up if its heartbeat is at most this old. */
 11	export const WORKER_STALE_MS = 3_000;
 12	
 13	export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';
 14	
 15	/** A row of the `jobs` table, as SQLite returns it. */
 16	export interface JobRow {
 17	  seq: number;
 18	  id: string;
 19	  status: JobStatus;
 20	  input: string;
 21	  steps: number;
 22	  fail_attempts: number;
 23	  attempts: number;
 24	  progress_completed: number;
 25	  result_output: string | null;
 26	  error: string | null;
 27	  idempotency_key: string | null;
 28	  run_after: number;
 29	  created_at: string;
 30	  updated_at: string;
 31	}
 32	
 33	/** The public JSON shape of a job. */
 34	export interface Job {
 35	  id: string;
 36	  status: JobStatus;
 37	  input: string;
 38	  steps: number;
 39	  failAttempts: number;
 40	  attempts: number;
 41	  progress: { completed: number; total: number };
 42	  result: { output: string } | null;
 43	  error: string | null;
 44	  createdAt: string;
 45	  updatedAt: string;
 46	}
 47	
 48	export interface Payload {
 49	  input: string;
 50	  steps: number;
 51	  failAttempts: number;
 52	}
 53	
 54	export function toJob(row: JobRow): Job {
 55	  return {
 56	    id: row.id,
 57	    status: row.status,
 58	    input: row.input,
 59	    steps: row.steps,
 60	    failAttempts: row.fail_attempts,
 61	    attempts: row.attempts,
 62	    progress: { completed: row.progress_completed, total: row.steps },
 63	    result: row.status === 'completed' ? { output: row.result_output ?? '' } : null,
 64	    error: row.status === 'failed' ? row.error : null,
 65	    createdAt: row.created_at,
 66	    updatedAt: row.updated_at,
 67	  };
 68	}
 69	
 70	type Param = string | number | null;
 71	
 72	function one(db: DatabaseSync, sql: string, ...params: Param[]): JobRow | undefined {
 73	  return db.prepare(sql).get(...params) as unknown as JobRow | undefined;
 74	}
 75	
 76	function many(db: DatabaseSync, sql: string, ...params: Param[]): JobRow[] {
 77	  return db.prepare(sql).all(...params) as unknown as JobRow[];
 78	}
 79	
 80	function mustOne(db: DatabaseSync, sql: string, ...params: Param[]): JobRow {
 81	  const row = one(db, sql, ...params);
 82	  if (!row) throw new Error(`expected a row for ${sql}`);
 83	  return row;
 84	}
 85	
 86	// ---- Server-side reads and writes ----
 87	
 88	export type SubmitOutcome = { kind: 'created' | 'replayed'; row: JobRow } | { kind: 'conflict' };
 89	
 90	/**
 91	 * Creates a job, or, when `key` matches an earlier submission, returns that job (same payload) or
 92	 * reports a conflict (different payload). The check and insert happen in one write transaction.
 93	 */
 94	export function submitJob(db: DatabaseSync, payload: Payload, key: string | null): SubmitOutcome {
 95	  return transaction<SubmitOutcome>(db, () => {
 96	    if (key !== null) {
 97	      const existing = one(db, 'SELECT * FROM jobs WHERE idempotency_key = ?', key);
 98	      if (existing) {
 99	        const same =
100	          existing.input === payload.input && existing.steps === payload.steps && existing.fail_attempts === payload.failAttempts;
101	        return same ? { kind: 'replayed', row: existing } : { kind: 'conflict' };
102	      }
103	    }
104	    const id = randomUUID();
105	    const now = new Date().toISOString();
106	    db.prepare(
107	      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, idempotency_key, run_after, created_at, updated_at)
108	       VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, 0, ?, ?)`,
109	    ).run(id, payload.input, payload.steps, payload.failAttempts, key, now, now);
110	    return { kind: 'created', row: mustOne(db, 'SELECT * FROM jobs WHERE id = ?', id) };
111	  });
112	}
113	
114	export function getJob(db: DatabaseSync, id: string): JobRow | undefined {
115	  return one(db, 'SELECT * FROM jobs WHERE id = ?', id);
116	}
117	
118	/** All jobs, newest first. */
119	export function listJobs(db: DatabaseSync): JobRow[] {
120	  return many(db, 'SELECT * FROM jobs ORDER BY seq DESC');
121	}
122	
123	export function workerIsUp(db: DatabaseSync, nowMs: number = Date.now()): boolean {
124	  const row = db.prepare('SELECT beat_at FROM worker_heartbeat WHERE id = 1').get() as { beat_at: number } | undefined;
125	  return row !== undefined && nowMs - Number(row.beat_at) < WORKER_STALE_MS;
126	}
127	
128	// ---- Worker-side reads and writes ----
129	
130	/**
131	 * Called once when the worker starts. Jobs left `running` by a worker that died are queued again.
132	 * If the interrupted attempt was the last one allowed and was set to fail, the job fails now.
133	 */
134	export function recoverInterruptedJobs(db: DatabaseSync): number {
135	  return transaction(db, () => {
136	    const now = new Date().toISOString();
137	    db.prepare(
138	      `UPDATE jobs SET status = 'failed', error = ?, result_output = NULL, updated_at = ?
139	       WHERE status = 'running' AND attempts >= ? AND attempts <= fail_attempts`,
140	    ).run(TRANSIENT_ERROR, now, MAX_ATTEMPTS);
141	    const result = db
142	      .prepare(`UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = 0, updated_at = ? WHERE status = 'running'`)
143	      .run(now);
144	    return Number(result.changes);
145	  });
146	}
147	
148	export function writeHeartbeat(db: DatabaseSync, nowMs: number = Date.now()): void {
149	  db.prepare(
150	    `INSERT INTO worker_heartbeat (id, beat_at) VALUES (1, ?)
151	     ON CONFLICT (id) DO UPDATE SET beat_at = excluded.beat_at`,
152	  ).run(nowMs);
153	}
154	
155	export function clearHeartbeat(db: DatabaseSync): void {
156	  db.prepare('DELETE FROM worker_heartbeat').run();
157	}
