159	/** Takes the oldest queued job that is due, marks it running and starts a new attempt. */
160	export function claimNextJob(db: DatabaseSync): JobRow | undefined {
161	  return transaction<JobRow | undefined>(db, () => {
162	    const next = one(
163	      db,
164	      `SELECT * FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq ASC LIMIT 1`,
165	      Date.now(),
166	    );
167	    if (!next) return undefined;
168	    db.prepare(
169	      `UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ? WHERE seq = ?`,
170	    ).run(new Date().toISOString(), next.seq);
171	    return mustOne(db, 'SELECT * FROM jobs WHERE seq = ?', next.seq);
172	  });
173	}
174	
175	export function setProgress(db: DatabaseSync, id: string, completed: number): void {
176	  db.prepare(`UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ?`).run(
177	    completed,
178	    new Date().toISOString(),
179	    id,
180	  );
181	}
182	
183	/** Returns a job to `queued` so that it can be claimed again once `runAfterMs` has passed. */
184	export function requeueJob(db: DatabaseSync, id: string, runAfterMs: number): void {
185	  db.prepare(
186	    `UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = ?, updated_at = ? WHERE id = ? AND status = 'running'`,
187	  ).run(runAfterMs, new Date().toISOString(), id);
188	}
189	
190	export function completeJob(db: DatabaseSync, id: string, output: string): void {
191	  const now = new Date().toISOString();
192	  db.prepare(
193	    `UPDATE jobs SET status = 'completed', result_output = ?, error = NULL,
194	       progress_completed = steps, updated_at = ?
195	     WHERE id = ? AND status = 'running'`,
196	  ).run(output, now, id);
197	}
