199	export function failJob(db: DatabaseSync, id: string, error: string): void {
200	  db.prepare(
201	    `UPDATE jobs SET status = 'failed', error = ?, result_output = NULL, updated_at = ?
202	     WHERE id = ? AND status = 'running'`,
203	  ).run(error, new Date().toISOString(), id);
204	}
