 19	/** Time for one processing step. */
 20	const STEP_MS = 100;
 21	const IDLE_POLL_MS = 200;
 22	const HEARTBEAT_MS = 1_000;
 23	
 24	const db: DatabaseSync = openDatabase();
 25	let stopping = false;
 26	
 27	for (const signal of ['SIGINT', 'SIGTERM'] as const) {
 28	  process.on(signal, () => {
 29	    stopping = true;
 30	  });
 31	}
