 33	/** Runs one attempt of a claimed job. `row.attempts` already counts this attempt. */
 34	async function runAttempt(row: JobRow): Promise<void> {
 35	  const { id, attempts, fail_attempts: failAttempts, steps, input } = row;
 36	
 37	  if (attempts <= failAttempts) {
 38	    // Simulated transient failure: fails at its first step, before any progress.
 39	    await sleep(STEP_MS);
 40	    if (stopping) return requeueJob(db, id, 0);
 41	    if (attempts >= MAX_ATTEMPTS) failJob(db, id, TRANSIENT_ERROR);
 42	    else requeueJob(db, id, Date.now() + RETRY_DELAY_MS);
 43	    return;
 44	  }
 45	
 46	  for (let completed = 1; completed <= steps; completed++) {
 47	    await sleep(STEP_MS);
 48	    if (stopping) return requeueJob(db, id, 0);
 49	    setProgress(db, id, completed);
 50	  }
 51	  completeJob(db, id, input.toUpperCase());
 52	}
 53	
 54	const recovered = recoverInterruptedJobs(db);
 55	if (recovered > 0) console.log(`requeued ${recovered} interrupted job(s)`);
 56	writeHeartbeat(db);
 57	const heartbeat = setInterval(() => writeHeartbeat(db), HEARTBEAT_MS);
 58	console.log('worker started');
 59	
 60	while (!stopping) {
 61	  let row: JobRow | undefined;
 62	  try {
 63	    row = claimNextJob(db);
 64	  } catch (e) {
 65	    console.error('failed to claim a job:', e);
 66	    await sleep(1_000);
 67	    continue;
 68	  }
 69	  if (!row) {
 70	    await sleep(IDLE_POLL_MS);
 71	    continue;
 72	  }
 73	  try {
 74	    await runAttempt(row);
 75	  } catch (e) {
 76	    console.error(`attempt on job ${row.id} failed:`, e);
 77	    try {
 78	      requeueJob(db, row.id, Date.now() + 1_000);
 79	    } catch {
 80	      // The job stays `running`; it is requeued when the worker next starts.
 81	    }
 82	  }
 83	}
 84	
 85	clearInterval(heartbeat);
 86	clearHeartbeat(db);
 87	db.close();
 88	console.log('worker stopped');
