  3	export interface FieldError {
  4	  field: string;
  5	  message: string;
  6	}
  7	
  8	export type Submission = { ok: true; payload: Payload; key: string | null } | { ok: false; fields: FieldError[] };
  9	
 10	const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
 11	const KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;
 12	
 13	function intField(obj: Record<string, unknown>, name: string, min: number, max: number, fallback: number, fields: FieldError[]): number {
 14	  if (!Object.hasOwn(obj, name)) return fallback;
 15	  const value = obj[name];
 16	  if (typeof value !== 'number' || !Number.isInteger(value) || value < min || value > max) {
 17	    fields.push({ field: name, message: `Must be an integer from ${min} to ${max}.` });
 18	    return fallback;
 19	  }
 20	  return value;
 21	}
 22	
 23	/**
 24	 * Validates a job submission: the Content-Type, the JSON body, and the Idempotency-Key header.
 25	 * Every offending field is reported, not just the first.
 26	 */
 27	export function validateSubmission(
 28	  contentType: string | undefined,
 29	  rawBody: string,
 30	  idempotencyKey: string | undefined,
 31	): Submission {
 32	  const fields: FieldError[] = [];
 33	
 34	  const media = contentType?.split(';')[0]?.trim().toLowerCase();
 35	  if (media !== 'application/json') {
 36	    fields.push({ field: 'body', message: 'Content-Type must be application/json.' });
 37	  }
 38	
 39	  if (idempotencyKey !== undefined && !KEY_PATTERN.test(idempotencyKey)) {
 40	    fields.push({ field: 'Idempotency-Key', message: 'Must match ^[A-Za-z0-9_-]{1,128}$.' });
 41	  }
 42	
 43	  let input = '';
 44	  let steps = 5;
 45	  let failAttempts = 0;
 46	
 47	  if (media === 'application/json') {
 48	    let parsed: unknown;
 49	    let parseFailed = false;
 50	    try {
 51	      parsed = JSON.parse(rawBody);
 52	    } catch {
 53	      parseFailed = true;
 54	    }
 55	    if (parseFailed) {
 56	      fields.push({ field: 'body', message: 'Request body must be valid JSON.' });
 57	    } else if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
 58	      fields.push({ field: 'body', message: 'Request body must be a JSON object.' });
 59	    } else {
 60	      const obj = parsed as Record<string, unknown>;
 61	      for (const key of Object.keys(obj)) {
 62	        if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'Unknown field.' });
 63	      }
 64	
 65	      if (!Object.hasOwn(obj, 'input')) {
 66	        fields.push({ field: 'input', message: 'Required.' });
 67	      } else if (typeof obj.input !== 'string') {
 68	        fields.push({ field: 'input', message: 'Must be a string.' });
 69	      } else if (obj.input.length < 1 || obj.input.length > 1000) {
 70	        fields.push({ field: 'input', message: 'Must be 1 to 1000 characters.' });
 71	      } else if (obj.input.trim() === '') {
 72	        fields.push({ field: 'input', message: 'Must not be only whitespace.' });
 73	      } else {
 74	        input = obj.input;
 75	      }
 76	
 77	      steps = intField(obj, 'steps', 1, 20, 5, fields);
 78	      failAttempts = intField(obj, 'failAttempts', 0, 5, 0, fields);
 79	    }
 80	  }
 81	
 82	  if (fields.length > 0) return { ok: false, fields };
 83	  return { ok: true, payload: { input, steps, failAttempts }, key: idempotencyKey ?? null };
 84	}
