  7	/** Largest request body accepted. A 1000-character input with every character escaped is well under this. */
  8	const MAX_BODY_BYTES = 64 * 1024;
  9	
 10	const db = openDatabase();
 11	const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
 12	
 13	function send(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
 14	  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
 15	  res.end(JSON.stringify(body));
 16	}
 17	
 18	function sendError(
 19	  res: ServerResponse,
 20	  status: number,
 21	  code: string,
 22	  message: string,
 23	  fields?: FieldError[],
 24	  headers: Record<string, string> = {},
 25	): void {
 26	  send(res, status, { error: fields ? { code, message, fields } : { code, message } }, headers);
 27	}
 28	
 29	/** Reads the request body. Resolves to null when the body exceeds MAX_BODY_BYTES. */
 30	function readBody(req: IncomingMessage): Promise<string | null> {
 31	  return new Promise((resolve, reject) => {
 32	    const chunks: Buffer[] = [];
 33	    let size = 0;
 34	    let tooLarge = false;
 35	    req.on('data', (chunk: Buffer) => {
 36	      size += chunk.length;
 37	      if (size > MAX_BODY_BYTES) {
 38	        tooLarge = true;
 39	        chunks.length = 0;
 40	        return;
 41	      }
 42	      if (!tooLarge) chunks.push(chunk);
 43	    });
 44	    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
 45	    req.on('error', reject);
 46	  });
 47	}
 48	
 49	async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
 50	  const raw = await readBody(req);
 51	  if (raw === null) {
 52	    return sendError(res, 400, 'invalid_request', 'The request is invalid.', [
 53	      { field: 'body', message: `Request body must be at most ${MAX_BODY_BYTES} bytes.` },
 54	    ]);
 55	  }
 56	  const key = req.headers['idempotency-key'];
 57	  const submission = validateSubmission(req.headers['content-type'], raw, typeof key === 'string' ? key : undefined);
 58	  if (!submission.ok) {
 59	    return sendError(res, 400, 'invalid_request', 'The request is invalid.', submission.fields);
 60	  }
 61	  const outcome = submitJob(db, submission.payload, submission.key);
 62	  if (outcome.kind === 'conflict') {
 63	    return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
 64	  }
 65	  send(res, outcome.kind === 'created' ? 201 : 200, toJob(outcome.row));
 66	}
 67	
 68	function methodNotAllowed(res: ServerResponse, allowed: string[]): void {
 69	  sendError(res, 405, 'method_not_allowed', `Method not allowed. Allowed: ${allowed.join(', ')}.`, undefined, {
 70	    allow: allowed.join(', '),
 71	  });
 72	}
 73	
 74	async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
 75	  const method = req.method ?? 'GET';
 76	  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
 77	
 78	  if (pathname === '/health') {
 79	    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
 80	    return send(res, 200, { status: 'ok', worker: workerIsUp(db) ? 'up' : 'down' });
 81	  }
 82	
 83	  if (pathname === '/') {
 84	    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
 85	    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
 86	    res.end(uiHtml);
 87	    return;
 88	  }
 89	
 90	  if (pathname === '/api/jobs') {
 91	    if (method === 'GET') return send(res, 200, { jobs: listJobs(db).map(toJob) });
 92	    if (method === 'POST') return handleCreate(req, res);
 93	    return methodNotAllowed(res, ['GET', 'POST']);
 94	  }
 95	
 96	  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
 97	  if (match) {
 98	    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
 99	    const id = decodeURIComponent(match[1]!);
100	    const row = getJob(db, id);
101	    if (!row) return sendError(res, 404, 'not_found', `No job with id ${id}.`);
102	    return send(res, 200, toJob(row));
103	  }
104	
105	  sendError(res, 404, 'not_found', `No route for ${pathname}.`);
106	}
107	
108	const port = Number(process.env.PORT ?? 3000);
109	const server = createServer((req, res) => {
110	  handle(req, res).catch((e: unknown) => {
111	    console.error('request failed:', e);
112	    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
113	    else res.end();
114	  });
115	});
116	
117	server.listen(port, () => console.log(`server listening on ${port}`));
118	
119	function shutdown(): void {
120	  server.close(() => {
121	    db.close();
122	    process.exit(0);
123	  });
124	  server.closeAllConnections();
125	  setTimeout(() => {
126	    db.close();
127	    process.exit(0);
128	  }, 2_000).unref();
129	}
130	
131	process.on('SIGTERM', shutdown);
132	process.on('SIGINT', shutdown);
