 48	    /** Numeric-looking text is sent as a number; anything else is sent as typed so the API can reject it. */
 49	    function asNumberIfNumeric(text) {
 50	      const trimmed = text.trim();
 51	      return /^[-+]?\d+(\.\d+)?$/.test(trimmed) ? Number(trimmed) : text;
 52	    }
 53	
 54	    function describeRejection(status, data) {
 55	      if (data && data.error) {
 56	        const fields = Array.isArray(data.error.fields) ? data.error.fields : [];
 57	        const details = fields.map((f) => `${f.field}: ${f.message}`).join(' ');
 58	        return `${data.error.message || 'Request rejected.'}${details ? ' ' + details : ''}`;
 59	      }
 60	      return `Request rejected (HTTP ${status}).`;
 61	    }
